diff --git a/api/tests/unit/stripe-v23.test.ts b/api/tests/unit/stripe-v23.test.ts
new file mode 100644
index 0000000..a3a2007
--- /dev/null
+++ b/api/tests/unit/stripe-v23.test.ts
@@ -0,0 +1,22 @@
+import { describe, expect, test } from "bun:test";
+import { readFileSync } from "fs";
+import { join } from "path";
+
+const root = join(import.meta.dir, "../..");
+const read = (p: string) => readFileSync(join(root, p), "utf8");
+
+describe("stripe-node 23 migration", () => {
+  test("installed stripe is v23", () => {
+    const pkg = JSON.parse(
+      readFileSync(join(root, "../node_modules/stripe/package.json"), "utf8")
+    );
+    expect(pkg.version.startsWith("23.")).toBe(true);
+  });
+  test("clients pin endive and intents drop payment_method_types", () => {
+    const src = read("src/helpers/paymentprovider.ts");
+    expect(src).toContain("2026-09-30.endive");
+    expect(src).not.toContain("payment_method_types");
+    expect(read("src/routes/stripe.ts")).toContain("retrieveCurrent()");
+    expect(read("src/routes/merchants.ts")).toContain("retrieveCurrent()");
+  });
+});
